CREATE POLICY tenant_isolation_venues ON venues FOR ALL USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);
DROP POLICY IF EXISTS public_read_venues ON venues;
CREATE POLICY public_read_venues ON venues FOR SELECT USING (current_setting('app.current_portal', true) IN ('public', 'customer') AND tenant_id IN (SELECT id FROM tenants WHERE status = 'ACTIVE'));
