DROP POLICY IF EXISTS staff_auth_lookup ON tenant_staff;
CREATE POLICY staff_auth_lookup ON tenant_staff FOR SELECT USING (current_setting('app.current_portal', true) = 'authentication' AND (lower(username) = NULLIF(current_setting('app.auth_identifier', true), '') OR lower(email) = NULLIF(current_setting('app.auth_identifier', true), '') OR phone = NULLIF(current_setting('app.auth_identifier', true), '') OR id::text = NULLIF(current_setting('app.auth_identifier', true), '')));
