DROP POLICY IF EXISTS customer_bookings ON bookings;
CREATE POLICY customer_bookings ON bookings FOR ALL USING (current_setting('app.current_portal', true) = 'customer' AND customer_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid) WITH CHECK (current_setting('app.current_portal', true) = 'customer' AND customer_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid);
DROP POLICY IF EXISTS tenant_isolation_booking_courts ON booking_courts;
ALTER TABLE booking_courts ENABLE ROW LEVEL SECURITY;
ALTER TABLE booking_courts FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation_booking_courts ON booking_courts;
CREATE POLICY tenant_isolation_booking_courts ON booking_courts FOR ALL USING (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid) WITH CHECK (tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')::uuid);
DROP POLICY IF EXISTS customer_booking_courts ON booking_courts;
CREATE POLICY customer_booking_courts ON booking_courts FOR ALL USING (current_setting('app.current_portal', true) = 'customer' AND EXISTS (SELECT 1 FROM bookings b WHERE b.id = booking_courts.booking_id AND b.tenant_id = booking_courts.tenant_id AND b.customer_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid)) WITH CHECK (current_setting('app.current_portal', true) = 'customer' AND EXISTS (SELECT 1 FROM bookings b WHERE b.id = booking_courts.booking_id AND b.tenant_id = booking_courts.tenant_id AND b.customer_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid));
