DROP POLICY IF EXISTS customer_audit ON audit_logs;
CREATE POLICY customer_audit ON audit_logs FOR INSERT WITH CHECK ((current_setting('app.current_portal', true) = 'customer' AND actor_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid AND actor_portal = 'customer') OR (current_setting('app.current_portal', true) = 'public' AND action = 'CUSTOMER_REGISTER' AND actor_portal = 'customer'));
DROP POLICY IF EXISTS global_audit ON audit_logs;
CREATE POLICY global_audit ON audit_logs FOR INSERT WITH CHECK (tenant_id IS NULL AND actor_portal = 'customer');
COMMIT;
